#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> edge(n);
    for (auto &e : edge) cin >> e;
    vector<char> done(n, 0);
    // pathOwner[v] == start means v is on the walk from `start`, at index pathIndex[v].
    vector<int> pathOwner(n, -1), pathIndex(n);
    vector<int> path;
    long long best = -1;
    for (int start = 0; start < n; start++) {
        if (done[start]) continue;
        path.clear();
        int node = start;
        while (node != -1 && !done[node] && pathOwner[node] != start) {
            pathOwner[node] = start;
            pathIndex[node] = path.size();
            path.push_back(node);
            node = edge[node];
        }
        if (node != -1 && !done[node] && pathOwner[node] == start) {
            long long sum = 0;
            for (size_t i = pathIndex[node]; i < path.size(); i++) sum += path[i];
            best = max(best, sum);
        }
        for (int u : path) done[u] = 1;
    }
    cout << best << "\n";
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        int[] edge = new int[n];
        for (int i = 0; i < n; i++) edge[i] = (int) next();
        boolean[] done = new boolean[n];
        // pathOwner[v] == start means v is on the walk from `start`, at index pathIndex[v].
        int[] pathOwner = new int[n], pathIndex = new int[n], path = new int[n];
        java.util.Arrays.fill(pathOwner, -1);
        long best = -1;
        for (int start = 0; start < n; start++) {
            if (done[start]) continue;
            int len = 0, node = start;
            while (node != -1 && !done[node] && pathOwner[node] != start) {
                pathOwner[node] = start;
                pathIndex[node] = len;
                path[len++] = node;
                node = edge[node];
            }
            if (node != -1 && !done[node] && pathOwner[node] == start) {
                long sum = 0;
                for (int i = pathIndex[node]; i < len; i++) sum += path[i];
                best = Math.max(best, sum);
            }
            for (int i = 0; i < len; i++) done[path[i]] = true;
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	edge := make([]int, n)
	for i := range edge {
		edge[i] = int(next())
	}
	done := make([]bool, n)
	// pathOwner[v] == start means v is on the walk from start, at index pathIndex[v].
	pathOwner := make([]int, n)
	pathIndex := make([]int, n)
	for i := range pathOwner {
		pathOwner[i] = -1
	}
	path := make([]int, 0, n)
	best := int64(-1)
	for start := 0; start < n; start++ {
		if done[start] {
			continue
		}
		path = path[:0]
		node := start
		for node != -1 && !done[node] && pathOwner[node] != start {
			pathOwner[node] = start
			pathIndex[node] = len(path)
			path = append(path, node)
			node = edge[node]
		}
		if node != -1 && !done[node] && pathOwner[node] == start {
			var sum int64
			for _, u := range path[pathIndex[node]:] {
				sum += int64(u)
			}
			best = max(best, sum)
		}
		for _, u := range path {
			done[u] = true
		}
	}
	fmt.Println(best)
}
